from glob import glob
import os
def task_func(directory, string):
    result = []
    for filepath in glob(os.path.join(directory, '**', '*.json'), recursive=True):
        try:
            with open(filepath, 'r') as f:
                data = json.load(f)
                if _search_json(data, string):
                    result.append(filepath)
        except (json.JSONDecodeError, UnicodeDecodeError):
            continue
    return result
def _search_json(data, string):
    if isinstance(data, dict):
        for key, value in data.items():
            if key == string or _search_json(value, string):
                return True
    elif isinstance(data, list):
        for item in data:
            if _search_json(item, string):
                return True
    else:
        return str(data) == string
    return False

