import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    data = json.loads(json_str)
    def process(obj):
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                if v is None:
                    continue
                new_dict[k] = process(v)
            return new_dict
        elif isinstance(obj, list):
            new_list = []
            for item in obj:
                if item is None:
                    continue
                new_list.append(process(item))
            return new_list
        elif isinstance(obj, str):
            email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
            return re.sub(email_pattern, REPLACE_NONE, obj)
        else:
            return obj
    processed = process(data)
    def collect_values(obj, values):
        if isinstance(obj, dict):
            for v in obj.values():
                collect_values(v, values)
        elif isinstance(obj, list):
            for item in obj:
                collect_values(item, values)
        else:
            values.append(obj)
    all_values = []
    collect_values(processed, all_values)
    counts = Counter(all_values)
    return {"data": processed, "value_counts": counts}

